import { test, expect } from '@playwright/test';

test.describe('Async Image Upload Progress', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/upload');
  });

  test('should display progress percentage during image upload', async ({ page }) => {
    const filePath = 'path/to/image.jpg';
    const uploadInput = page.getByLabel('Upload Image');

    await uploadInput.setInputFiles(filePath);

    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    const progressText = page.getByText(/uploading/i);
    await expect(progressText).toBeVisible();

    await expect(progressBar).toHaveAttribute('aria-valuenow', '100');
  });

  test('should show success message after upload completion', async ({ page }) => {
    const filePath = 'path/to/image.jpg';
    const uploadInput = page.getByLabel('Upload Image');

    await uploadInput.setInputFiles(filePath);

    const successMessage = page.getByText(/upload successful/i);
    await expect(successMessage).toBeVisible();
  });
});
